<script setup lang="ts">
import { Plus, Minus, RotateCcw } from 'lucide-vue-next'
import { normalizePalette, makeColor, normalizeHex, tones, toneLabels, type Palette } from '@qinbian/shared'
const props=defineProps<{modelValue:Palette;readonly?:boolean;usedTokens?:string[]}>(),emit=defineEmits<{'update:modelValue':[p:Palette]}>(),ctx=useQinbian()
const palette=computed(()=>props.modelValue)
function update(fn:(p:Palette)=>void){const p=structuredClone(toRaw(palette.value));fn(p);emit('update:modelValue',p)}
function changeColor(index:number,tone:'regular'|'highlight'|'light',value:string){const hex=normalizeHex(value);if(!hex){ctx.notify('请填写有效的十六进制颜色，例如 #183A49',true);return}update(p=>{if(tone==='regular')p.colors[index]={...p.colors[index]!,...makeColor(p.colors[index]!.id,p.colors[index]!.name,hex)};else p.colors[index]![tone]=hex})}
function add(){if(palette.value.colors.length>=6)return;const options=['#183A49','#567067','#9E4B3B','#B38A55','#8A8393','#5B8790'],names=['墨蓝','灰青','朱砂','浅金','黛紫','石青'];update(p=>{const n=Array.from({length:6},(_,i)=>i+1).find(i=>!p.colors.some(c=>c.id==='color'+i))!;p.colors.push(makeColor('color'+n,names[n-1]!,options[n-1]!))})}
function remove(){if(palette.value.colors.length<=3)return;const c=palette.value.colors.at(-1)!;if(props.usedTokens?.some(t=>t.startsWith(c.id+'-'))){ctx.notify('最后一色仍有映射，请先将相关元素映射到其他颜色',true);return}update(p=>p.colors.pop())}
</script>
<template><div class="palette-editor"><div class="palette-count"><span>{{palette.colors.length}} 色配色 · 每色三档</span><div><button class="icon-button" aria-label="减少一色" :disabled="readonly||palette.colors.length<=3" @click="remove"><Minus :size="15"/></button><button class="icon-button" aria-label="增加一色" :disabled="readonly||palette.colors.length>=6" @click="add"><Plus :size="15"/></button></div></div><label class="palette-title-input">配色名称<input :value="palette.name" :readonly="readonly" @input="update(p=>p.name=($event.target as HTMLInputElement).value)"></label><div v-for="(c,index) in palette.colors" :key="c.id" class="palette-edit-row"><div class="palette-name-edit"><input :value="c.name" :readonly="readonly" :aria-label="c.id+' 颜色名称'" @input="update(p=>p.colors[index]!.name=($event.target as HTMLInputElement).value)"><code>{{c.id}}</code><button class="icon-button" :aria-label="'重新搭配 '+c.name" :disabled="readonly" title="根据主题色重新搭配另外两档" @click="update(p=>p.colors[index]=makeColor(c.id,c.name,c.regular))"><RotateCcw :size="13"/></button></div><div class="palette-variant-edit"><label v-for="tone in tones" :key="tone"><span>{{toneLabels[tone]}}</span><div><input type="color" :value="c[tone]" :disabled="readonly" :aria-label="c.name+' '+toneLabels[tone]" @input="changeColor(index,tone,($event.target as HTMLInputElement).value)"><input :value="c[tone]" :readonly="readonly" :aria-label="c.id+'-'+tone+' 色值'" @change="changeColor(index,tone,($event.target as HTMLInputElement).value)"></div><small>{{c.id}}-{{tone}}</small></label></div></div></div></template>
